import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"界面规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/developers/design-system.md","filePath":"zh/developers/design-system.md","lastUpdated":1793111003000}'),a={name:"zh/developers/design-system.md"};function r(s,e,i,l,n,p){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="界面规范" tabindex="-1">界面规范 <a class="header-anchor" href="#界面规范" aria-label="Permalink to &quot;界面规范&quot;">​</a></h1><p>工作区参考 <a href="https://ui.shadcn.com/" target="_blank" rel="noreferrer">shadcn/ui</a> 的 new-york 与 neutral 风格，使用原生 CSS 和 Vue 3 组件实现，不依赖 CSS 框架或 React 运行时。</p><h2 id="文件归属" tabindex="-1">文件归属 <a class="header-anchor" href="#文件归属" aria-label="Permalink to &quot;文件归属&quot;">​</a></h2><p>以下路径均相对于 <code>web/src</code>。</p><table tabindex="0"><thead><tr><th>层次</th><th>内容</th><th>文件</th></tr></thead><tbody><tr><td>设计变量</td><td>颜色、图表配色、圆角、阴影、字体，如 <code>--background</code>、<code>--muted-foreground</code>、<code>--radius-md</code></td><td><code>styles/ui.css</code> 的 <code>:root</code></td></tr><tr><td>基础控件</td><td>按钮、输入、选择、卡片、徽标、标签、表格、列表、侧栏、统计与进度条</td><td><code>styles/ui.css</code></td></tr><tr><td>外壳与浮层</td><td>滚动、侧栏收起、移动端抽屉、弹窗、菜单、列表框、提示与骨架屏</td><td><code>styles/app.css</code></td></tr><tr><td>字体</td><td>自托管 Geist 与 Geist Mono，中文回退到系统无衬线字体</td><td><code>styles/fonts.css</code></td></tr><tr><td>共享组件</td><td><code>UiSelect</code>、<code>UiMenu</code>、<code>UiSheet</code>、<code>AppDialog</code>、<code>Disclosure</code>、<code>StatusBadge</code>、<code>Toaster</code>、<code>Icon</code></td><td><code>components/</code></td></tr></tbody></table><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h2><ul><li>复用设计变量，不在业务模块中硬编码颜色、圆角或阴影。</li><li>新增类名前先复用基础样式（<code>.btn</code>、<code>.input</code>、<code>.select</code>、<code>.card</code>、<code>.field</code>、<code>.page</code>、<code>.hdr</code>）和共享组件。页面专属样式靠近页面代码放置，不在样式表末尾堆叠覆盖规则。</li><li>正文与控件为 14px／20px，元数据为 12px。小于 900px 的屏幕将输入字号改为 16px，避免移动浏览器自动缩放。</li><li>侧栏宽 288px，可完全收起；小于 900px 时使用抽屉。主内容区滚动，侧栏历史、弹窗、图谱及有界列表可各自滚动。</li><li>不仅依靠颜色传递含义：错误、状态和选择还需文本或图标。网络图按节点角色分类着色，分布图使用蓝色图表配色。</li><li>长篇综述保留适合阅读的字号和行高，不沿用密集卡片样式。</li><li>工作区仅提供浅色主题。</li></ul><p>在线版使用相同 Web 源码，因此共享视觉变更应在社区版完成。</p><h2 id="检查变更" tabindex="-1">检查变更 <a class="header-anchor" href="#检查变更" aria-label="Permalink to &quot;检查变更&quot;">​</a></h2><p>在 <code>web/</code> 中运行 <code>npm run typecheck</code>、<code>npm run build</code> 和 <code>npm run test:browser</code>，并在真实浏览器中检查桌面与手机宽度。</p>',10)])])}const m=d(a,[["render",r]]);export{u as __pageData,m as default};
